mapper.select:
SELECT ID, CABINET_NO, TOOL_CODE, POSITION, STATUS, CREATE_TIME, UPDATE_TIME
FROM TOOL_CABINET_INVENTORY
WHERE CABINET_NO = #{cabinetNo}
  AND STATUS = #{status}
ORDER BY POSITION

SELECT ID, CABINET_NO, TOOL_CODE, POSITION, STATUS, CREATE_TIME, UPDATE_TIME
FROM TOOL_CABINET_INVENTORY
WHERE TOOL_CODE = #{toolCode}

SELECT ID, CABINET_NO, TOOL_CODE, POSITION, STATUS, CREATE_TIME, UPDATE_TIME
FROM TOOL_CABINET_INVENTORY
WHERE CABINET_NO = #{cabinetNo}
  AND POSITION = #{position}

mapper.update:
UPDATE TOOL_CABINET_INVENTORY
SET STATUS = #{status}, UPDATE_TIME = SYSDATE
WHERE ID = #{id}

UPDATE TOOL_CABINET_INVENTORY
SET STATUS = #{status}, UPDATE_TIME = SYSDATE
WHERE TOOL_CODE = #{toolCode}
